import openpyxl, os

base_dir = '/filesystem/final_batch4__mechanical_task5_pcw_flush_mop__blind'

def inspect_xlsx(relpath):
    path = os.path.join(base_dir, relpath)
    wb = openpyxl.load_workbook(path, data_only=True)
    print(f'=== {relpath} ===')
    for sheetname in wb.sheetnames:
        sheet = wb[sheetname]
        print(f'-- Sheet: {sheetname} ({sheet.max_row} rows, {sheet.max_column} cols) --')
        for r in range(1, min(sheet.max_row + 1, 30)):
            row_vals = [sheet.cell(r, c).value for c in range(1, min(sheet.max_column + 1, 15))]
            if any(v is not None for v in row_vals):
                print(f'R{r}: {row_vals}')
    print()

for root, dirs, files in os.walk(base_dir):
    for f in sorted(files):
        if f.endswith('.xlsx'):
            inspect_xlsx(os.path.relpath(os.path.join(root, f), base_dir))
