    print(f'=== {relpath} ({len(doc)} pages) ===')
    for i, page in enumerate(doc):
        text = page.get_text()
        print(f'--- Page {i+1} (text len {len(text)}) ---')
        if text.strip():
            print(text[:1000])
        else:
            print('[NO TEXT LAYER / IMAGE PAGE]')
